//
// Corresponds with GET /api/v2/deleted_users (the `ListDeletedUsers` operationId).
func (c *Client) ListDeletedUsers(ctx context.Context, params *ListDeletedUsersParams, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewListDeletedUsersRequest(c.Server, params)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

